package edu.pe.cibertec.saibm.libro.infrastructure.in.rest;
import java.net.URI; import java.util.stream.Collectors; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import edu.pe.cibertec.saibm.libro.domain.exception.*;
@RestControllerAdvice public class LibroExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ProblemDetail validation(MethodArgumentNotValidException e,HttpServletRequest r){var p=problem(HttpStatus.BAD_REQUEST,"Invalid request","Request validation failed",r);p.setProperty("errors",e.getBindingResult().getFieldErrors().stream().collect(Collectors.toMap(x->x.getField(),x->x.getDefaultMessage(),(a,b)->a)));return p;} @ExceptionHandler(WriteAuthorizationException.class) ProblemDetail forbidden(HttpServletRequest r){return problem(HttpStatus.FORBIDDEN,"Forbidden","Write authorization required",r);} @ExceptionHandler({InvalidRequestException.class,InvalidBookException.class}) ProblemDetail invalid(RuntimeException e,HttpServletRequest r){return problem(HttpStatus.BAD_REQUEST,"Invalid request",e.getMessage(),r);} @ExceptionHandler(BookNotFoundException.class) ProblemDetail missing(RuntimeException e,HttpServletRequest r){return problem(HttpStatus.NOT_FOUND,"Book not found",e.getMessage(),r);} private ProblemDetail problem(HttpStatus s,String t,String d,HttpServletRequest r){var p=ProblemDetail.forStatusAndDetail(s,d);p.setTitle(t);p.setType(URI.create("urn:saibm:libro:"+s.value()));p.setInstance(URI.create(r.getRequestURI()));return p;} }
